function makeField(){let n=65,z=[];for(let j=0;j<n;j++){let row=[];for(let i=0;i<n;i++){let x=(i-32)/22,y=(j-32)/24;let theta=Math.atan2(y,x),r=Math.sqrt(x*x+y*y);let d=r*(1+.16*Math.cos(theta)-.04*Math.sin(2*theta));row.push(d*d)}z.push(row)}return {psi:z,R:Array.from({length:n},(_,i)=>1.35+i*.0125),Z:Array.from({length:n},(_,i)=>-.4+i*.0125),time_ms:0}}
