let axis=f.axis||f.efit_axis||null;if(state.layers.axis){let ax=axis?.R??axis?.r??f.r_axis,az=axis?.Z??axis?.z??f.z_axis;if(Number.isFinite(+ax)&&Number.isFinite(+az)){const px=mapR(+ax,f,ox,scale,nx),py=mapZ(+az,f,oy,scale,ny);g.beginPath();g.strokeStyle='#fde047';g.lineWidth=1;g.moveTo(px-6,py);g.lineTo(px+6,py);g.moveTo(px,py-6);g.lineTo(px,py+6);g.stroke()}else if(!state.record){let px=ox+nx*scale*.49,py=oy+ny*scale*.51;g.beginPath();g.strokeStyle='#fde047';g.moveTo(px-6,py);g.lineTo(px+6,py);g.moveTo(px,py-6);g.lineTo(px,py+6);g.stroke()}}
