function onPointer(e){let p=$('#flux-canvas')._plot;if(!p)return;let rect=e.currentTarget.getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top,i=Math.floor((x-p.ox)/p.scale),j=Math.floor((p.oy+p.ny*p.scale-y)/p.scale);if(i<0||j<0||i>=p.nx||j>=p.ny)return;let f=activeGrid(),v=f.psi?.[j]?.[i]??f.efit_psirz?.[state.frame]?.[j]?.[i];let R=f.R||f.efit_grid_R,Z=f.Z||f.efit_grid_Z;$('#coord-readout').textContent=`R ${(R?.[i]??1.35+i*.0125).toFixed(3)}   Z ${(Z?.[j]??-.4+j*.0125).toFixed(3)}   ψ ${Number(v).toPrecision(4)}`}
function updateFrameMetrics(){let f=state.fluxSource==='prediction'&&state.prediction?.record_id===state.record?.id?state.prediction.frames[state.frame]:selectedFrame();if(!f)return;let a=f.axis||{};$('#axis-r').textContent=Number.isFinite(+a.R)?`${(+a.R).toFixed(3)} m`:'Unavailable';$('#axis-z').textContent=Number.isFinite(+a.Z)?`${(+a.Z).toFixed(3)} m`:'Unavailable';$('#psi-axis').textContent=Number.isFinite(+f.psi_axis)?Number(f.psi_axis).toExponential(3):'Unavailable';$('#grid-spacing').textContent=(f.R?.length||f.efit_grid_R?.length)?`${(f.R||f.efit_grid_R).length} × ${(f.Z||f.efit_grid_Z).length}`:'Unavailable'}
function updateTimeline(){let fs=frameList(),count=frameCount(),times=state.record?.times||fs.map(f=>f.time_ms),slider=$('#time-slider');if(!slider)return;slider.max=Math.max(0,count-1);slider.value=Math.min(state.frame,Math.max(0,count-1));$('#frame-count').textContent=count?`${String(state.frame+1).padStart(2,'0')} / ${count} TIME SAMPLES`:'NO TIME DATA';$('#time-start').textContent=count?`${Number(times[0]??fs[0]?.time_ms).toFixed(1)} ms`:'—';$('#time-end').textContent=count?`${Number(times.at(-1)??fs.at(-1)?.time_ms).toFixed(1)} ms`:'—';$('#frame-ticks').style.backgroundSize=count>1?`${100/(count-1)}% 100%`:'100% 100%'}
function step(n){let count=frameCount();if(!count)return;state.frame=(state.frame+n+count)%count;renderPage()}
let playTimer;function togglePlay(){if(state.playing){clearInterval(playTimer);state.playing=false;$('#play-button').textContent='▶'}else if(frameCount()){state.playing=true;$('#play-button').textContent='Ⅱ';let rate=+$(' #play-rate')?.value||1;playTimer=setInterval(()=>{state.frame=(state.frame+1)%frameCount();renderPage()},Math.max(80,500/rate))}else toast('Load a record with equilibrium frames to play the discharge timeline.')}
async function connectData(){const b=$('#connect-data');b.disabled=true;b.textContent='Loading…';try{let res=await fetch('/api/catalog');let local=await res.json();if(local.records?.length){state.catalog=local;state.record=state.catalog.records.find(x=>x.machine===state.machine)||state.catalog.records[0];state.machine=state.record.machine;toast(`${state.catalog.records.length} curated records loaded`);renderPage();return}const config=state.machine==='DIII-D'?'diii_d_train':'mast_public_test',split=config==='diii_d_train'?'train':'public_test';let u=`https://datasets-server.huggingface.co/rows?dataset=Sophelio%2Ffusion-equilibrium-challenge&config=${config}&split=${split}&offset=0&length=1`;let remote=await fetch(u);if(!remote.ok)throw Error(`Dataset service returned ${remote.status}`);let data=await remote.json();if(data.error||!data.rows?.length)throw Error(data.error||'No rows returned');state.catalog.records=data.rows.map(x=>normalizeRow(x.row,config));state.record=state.catalog.records[0];renderPage();toast('Loaded one upstream record for this session. Run data:bootstrap to save it locally.')}catch(e){toast(`Dataset unavailable: ${e.message.slice(0,100)}. Try again when Hugging Face is reachable.`)}finally{b.disabled=false;b.textContent='↗ Connect data'}}
function normalizeRow(row,config){let machine=config.startsWith('diii')?'DIII-D':'MAST',id=row.record_id||row.id||row.shot_id||`${machine}_${row.record_index??row.index??'released-record'}`,times=row.efit_times||[],maps=row.efit_psirz||[];return {id,machine,record_id:id,configuration:config,reference_available:Array.isArray(maps)&&maps.length>0,frames:Array.from(times,(time,i)=>maps[i]?({time_ms:time,psi:maps[i],R:row.efit_grid_R,Z:row.efit_grid_Z,boundary:row.efit_lcfs_r?.[i]?.slice(0,row.efit_lcfs_n?.[i]).map((r,j)=>[r,row.efit_lcfs_z?.[i]?.[j]]),axis:row.efit_r_axis?{R:row.efit_r_axis[i],Z:row.efit_z_axis?.[i]}:null,psi_axis:row.efit_psi_axis?.[i]}):null).filter(Boolean),times,frame_count:times.length}}
function renderPage(){let route=state.route;if(!pages[route])route='explorer';$('#crumb-current').textContent=pages[route][0];$$('.nav-item').forEach(a=>a.classList.toggle('active',a.dataset.route===route));$('#timeline-bar').style.display=route==='explorer'?'':'none';if(route==='explorer'){renderExplorer();return}renderModule(route);}
function renderModule(route){const [label,sub]=pages[route];let body='';if(route==='overview'){let records=state.catalog.records,di=records.filter(r=>r.machine==='DIII-D'),mast=records.filter(r=>r.machine==='MAST'),refs=records.filter(r=>r.reference_available),frames=records.reduce((n,r)=>n+(r.frames?.length||0),0);body=`<div class="module-grid"><article class="module-card"><div class="module-value">${records.length}</div><h3>Curated local records</h3><p>Counts come from the local catalog, never the upstream corpus total.</p></article><article class="module-card"><div class="module-value">${frames}</div><h3>Reference frames indexed</h3><p>${refs.length} record(s) currently include released EFIT flux frames.</p></article><article class="module-card"><div class="module-value">${di.length} / ${mast.length}</div><h3>DIII-D / MAST records</h3><p>Machine coverage in this local catalog. Public test references remain unavailable.</p></article></div><div class="method-block"><h3>Explore magnetic confinement</h3><p>Investigate the geometry, topology, and temporal evolution of released tokamak equilibria. Training references and withheld test targets are kept distinct at the data-contract level.</p><button class="small-button" id="open-explorer">Open discharge explorer →</button> &nbsp; <button class="small-button" id="connect-overview">Connect official data</button></div>`}else if(route==='catalog'){let rows=state.catalog.records.map(r=>`<tr><td>${esc(r.machine)}</td><td>${esc(recordName(r))}</td><td>${esc(r.configuration||'Challenge dataset')}</td><td>${r.frames?.length||'—'}</td><td>${r.reference_available?'Available':'Withheld'}</td><td><button class="small-button open-record" data-id="${esc(r.id)}">Open explorer</button></td></tr>`).join('');body=`<section class="panel"><div class="panel-head"><span class="panel-title">RELEASED RECORDS</span><span class="head-spacer"></span><input class="control-select" id="catalog-search" placeholder="Filter records" aria-label="Filter records"></div><table class="catalog-table"><thead><tr><th>MACHINE</th><th>RECORD ID</th><th>CONFIGURATION</th><th>FRAMES</th><th>REFERENCE</th><th>WORKSPACE</th></tr></thead><tbody id="catalog-body">${rows||'<tr><td colspan="6">No curated records available. Connect the official source or run the bootstrap command.</td></tr>'}</tbody></table></section>`}else if(route==='sources'){body=`<div class="module-grid"><article class="module-card"><div class="module-value">DIII-D</div><h3>Official starter demo · shot 203702</h3><p>DIII-D Parquet demo with released EFIT reference frames and diagnostic inputs.</p></article><article class="module-card"><div class="module-value">MAST</div><h3>Official starter demo · shot 28348</h3><p>MAST Parquet demo with released EFIT reference frames and diagnostic inputs. This is separate from the challenge public-test split.</p></article><article class="module-card"><div class="module-value">Sophelio</div><h3>Dataset attribution</h3><p>Sources: Sophelio Fusion Equilibrium Challenge and official starter kit. Demo shot IDs come from the official filenames; each catalog record carries its source URL, revision, and SHA-256 digest.</p></article></div><div class="method-block"><h3>Dataset release</h3><p>The default bounded selection downloads official starter-kit Parquet demos. Optional challenge ingestion uses the Hugging Face Dataset Viewer. Raw records are preserved with configuration, revision, source URL, and digest metadata.</p></div><div class="method-block"><h3>Upstream availability</h3><p>Hugging Face Dataset Viewer may temporarily suspend a configuration's rows endpoint during resource spikes. The bootstrap command reports such failures and never replaces them with generated values.</p></div><p><a class="source-link" href="https://huggingface.co/datasets/Sophelio/fusion-equilibrium-challenge" target="_blank" rel="noreferrer">Official dataset ↗</a> &nbsp; <a class="source-link" href="https://github.com/Sophelio/fusion-equilibrium-challenge-starter" target="_blank" rel="noreferrer">Official starter kit ↗</a></p>`}else if(route==='methodology'){body=`<div class="method-block"><h3>Poloidal flux</h3><p>The scalar field ψ(R,Z) describes the axisymmetric poloidal magnetic flux. A flux surface is a contour of constant ψ in the poloidal plane. It is not a particle trajectory; strong parallel motion follows the corresponding three-dimensional magnetic surface.</p><div class="equation">ψ<sub>N</sub> = (ψ − ψ<sub>axis</sub>) / (ψ<sub>boundary</sub> − ψ<sub>axis</sub>)</div><p>Normalization is valid only when axis and boundary flux are supplied or reliably identified and the denominator is nonzero. The app does not infer toroidal flux from ψ<sub>N</sub>.</p></div><div class="method-block"><h3>Equilibrium provenance</h3><p>Training records may include EFIT reference reconstructions. DIII-D public test and MAST public test withhold targets. A withheld reference cannot support reference-versus-prediction error metrics; the interface disables those comparisons. Any imported prediction remains model-predicted.</p></div><div class="method-block"><h3>Geometry extraction</h3><p>Contours are linearly interpolated on the supplied grid with marching squares. Grid shape and coordinate vectors are retained. Smoother drawing is not increased measurement resolution. Magnetic axis and X-point labels are shown only when supplied or extracted with a documented stationary-point method; ambiguous topology is marked unavailable.</p></div><div class="method-block"><h3>Limitations</h3><p>Axisymmetric equilibrium frames do not establish three-dimensional MHD stability or turbulence. Diagnostics and equilibrium frames use different time bases. No interpolation is performed across missing target frames, and no wall geometry is introduced without a traceable source.</p></div>`}else if(route==='compare'){let a=state.record||state.catalog.records.find(r=>r.machine==='DIII-D'),others=state.catalog.records.filter(r=>r.id!==a?.id),b=others.find(r=>r.id===state.compareId)||others.find(r=>r.machine!==a?.machine)||others[0],time=frameTime(),fa=nearestRecordFrame(a,time),fb=nearestRecordFrame(b,time),frames=[fa?.frame,fb?.frame].filter(f=>f?.boundary?.length),all=frames.flatMap(f=>f.boundary),bounds=all.length?[Math.min(...all.map(p=>+p[0])),Math.max(...all.map(p=>+p[0])),Math.min(...all.map(p=>+p[1])),Math.max(...all.map(p=>+p[1]))]:[0,1,0,1],dist=boundaryDistance(fa?.frame?.boundary,fb?.frame?.boundary),metrics=[['Major radius',g=>g?.major_radius_m,'m'],['Minor radius',g=>g?.minor_radius_m,'m'],['Aspect ratio',g=>g?.aspect_ratio,''],['Elongation',g=>g?.elongation,''],['Upper triangularity',g=>g?.triangularity?.upper,''],['Lower triangularity',g=>g?.triangularity?.lower,''],['Cross-sectional area',g=>g?.cross_sectional_area_m2,'m²'],['Axisymmetric volume',g=>g?.axisymmetric_volume_m3,'m³']];body=b&&fa&&fb?`<div class="comparison-tools"><span>ALIGNMENT · NEAREST RECORDED FRAME TO ${time==null?'FIRST AVAILABLE TIME':Number(time).toFixed(2)+' ms'}</span><select class="control-select" id="compare-record">${others.map(r=>`<option value="${esc(r.id)}" ${r.id===b.id?'selected':''}>${esc(r.machine)} · ${esc(recordName(r))}</option>`).join('')}</select></div><div class="comparison-maps"><section class="panel"><div class="panel-head"><span class="panel-title">${esc(a.machine)} · ${esc(recordName(a))}</span><span class="head-spacer"></span><span class="head-chip">${fa.frame.time_ms.toFixed(2)} ms${fa.offset_ms==null?'':` · Δ ${fa.offset_ms.toFixed(2)} ms`}</span></div>${comparisonSvg(fa.frame,bounds)}</section><section class="panel"><div class="panel-head"><span class="panel-title">${esc(b.machine)} · ${esc(recordName(b))}</span><span class="head-spacer"></span><span class="head-chip">${fb.frame.time_ms.toFixed(2)} ms${fb.offset_ms==null?'':` · Δ ${fb.offset_ms.toFixed(2)} ms`}</span></div>${comparisonSvg(fb.frame,bounds)}</section></div><section class="panel comparison-table-wrap"><div class="panel-head"><span class="panel-title">DERIVED GEOMETRY · SOURCE LCFS</span><span class="head-spacer"></span><span class="head-chip">COMMON SI UNITS</span></div><table class="catalog-table"><thead><tr><th>QUANTITY</th><th>${esc(a.machine)}</th><th>${esc(b.machine)}</th><th>DIFFERENCE · B−A</th></tr></thead><tbody>${metrics.map(([label,get,unit])=>{let av=get(fa.frame.geometry),bv=get(fb.frame.geometry);return `<tr><td>${label} ${unit}</td><td>${Number.isFinite(+av)?Number(av).toFixed(4):'Unavailable'}</td><td>${Number.isFinite(+bv)?Number(bv).toFixed(4):'Unavailable'}</td><td>${Number.isFinite(+av)&&Number.isFinite(+bv)?(Number(bv)-Number(av)).toFixed(4):'Unavailable'}</td></tr>`}).join('')}<tr><td>Mean symmetric boundary distance [m]</td><td colspan="2">${dist?dist.mean_symmetric_m.toFixed(4):'Unavailable'}</td><td>Hausdorff ${dist?dist.hausdorff_m.toFixed(4)+' m':'Unavailable'}</td></tr></tbody></table><p class="inspector-note">Boundary metrics compare the sampled source LCFS polygons directly in physical R-Z coordinates. Frame times are nearest-neighbour aligned; no flux-map subtraction or time interpolation is performed. Positive metric differences mean ${esc(b.machine)} minus ${esc(a.machine)}.</p></section>`:`<section class="panel"><div class="empty-state"><div class="empty-card"><h2>Two source records are needed</h2><p>The local catalog currently has ${state.catalog.records.length} records. Bootstrap one record per machine to use the cross-machine comparison.</p></div></div></section>`}else if(route==='magnetic-geometry'){let f=selectedFrame(),g=f?.geometry;body=`<section class="panel surface-workspace"><div class="panel-head"><span class="panel-title">3D AXISYMMETRIC LCFS SURFACE</span><span class="panel-subtitle">Revolved from the selected source contour</span><span class="head-spacer"></span><span class="head-chip">${g?esc(g.provenance.toUpperCase()):'BOUNDARY UNAVAILABLE'}</span><button class="small-button" id="surface-wire">Wireframe</button><button class="small-button" id="surface-reset">Reset camera</button></div><canvas id="surface-canvas" aria-label="Interactive axisymmetric three-dimensional surface generated from the selected LCFS"></canvas></section><div class="method-block"><h3>What this surface represents</h3><p>The mesh is generated by revolving the selected frame's source LCFS coordinates around the tokamak symmetry axis. It preserves the measured poloidal contour shape. It is an axisymmetric geometric representation, not a three-dimensional MHD simulation. No helical field lines are drawn because the selected data do not supply the complete magnetic-field components needed for quantitative tracing. ${g?`Selected frame: ${Number(f.time_ms).toFixed(2)} ms · geometric major radius ${Number(g.major_radius_m).toFixed(3)} m · minor radius ${Number(g.minor_radius_m).toFixed(3)} m.`:'No valid boundary is available.'}</p></div>`}else if(route==='topology'){let f=selectedFrame(),t=f?.topology;body=`<div class="module-grid"><article class="module-card"><div class="module-value">${t?.o_points?.length??'—'}</div><h3>O-point candidates</h3><p>Grid-local extrema; these are candidates at the released resolution, not sub-grid refined points.</p></article><article class="module-card"><div class="module-value">${t?.x_points?.length??'—'}</div><h3>X-point candidates</h3><p>Bilinear-cell stationary saddles located within source grid cells.</p></article><article class="module-card"><h3>Quality state</h3><p>${esc(t?.quality||'Topology has not been processed for this frame.')}</p></article></div><div class="method-block"><h3>Candidate inspection</h3><p>Topology candidates are derived from the supplied EFIT ψ(R,Z) grid. The method checks eight-neighbour extrema and stationary points of each bilinear cell interpolant. It does not perform sub-grid root refinement, prove separatrix connectivity, or identify a complete LCFS. Candidate points appear as pink crosses in the explorer when the layer is enabled.</p><table class="catalog-table"><thead><tr><th>TYPE</th><th>R [m]</th><th>Z [m]</th><th>ψ</th><th>QUALITY</th></tr></thead><tbody>${[...(t?.o_points||[]).map(p=>({...p,type:'O-point'})),...(t?.x_points||[]).map(p=>({...p,type:'X-point'}))].slice(0,100).map(p=>`<tr><td>${p.type}</td><td>${Number(p.R_m).toFixed(5)}</td><td>${Number(p.Z_m).toFixed(5)}</td><td>${Number(p.psi).toExponential(4)}</td><td>${esc(p.quality||p.classification)}</td></tr>`).join('')||'<tr><td colspan="5">No stationary candidates resolved for the selected frame.</td></tr>'}</tbody></table></div>`}else if(route==='predictions'){let p=state.prediction?.record_id===state.record?.id?state.prediction:null;body=`<section class="panel"><div class="panel-head"><span class="panel-title">MODEL OUTPUT IMPORT</span><span class="head-spacer"></span><span class="head-chip">JSON · VALIDATED · NO CODE EXECUTION</span></div><div class="prediction-body"><p class="inspector-note">Import one numeric model result for ${state.record?esc(recordName(state.record)):'the selected record'}. Validation checks record identity, dataset revision, timestamp order, physical coordinates, units, grid shape, and finite values.</p><label class="prediction-file-label" for="prediction-file">Choose prediction JSON</label><input id="prediction-file" type="file" accept="application/json,.json" aria-label="Import prediction JSON"><div class="prediction-status" id="prediction-status">${p?`Loaded ${esc(p.model.name||p.model.id)} ${esc(p.model.version)} · ${p.frames.length} frames · ${esc(p.units.psi)}`:'No prediction imported for the selected record.'}</div>${p?`<div class="prediction-actions"><button class="small-button" id="show-prediction">Open predicted equilibrium</button><button class="small-button" id="clear-prediction">Remove local import</button></div><p class="inspector-note">Provenance: Model-predicted equilibrium. Reference availability: ${state.record.reference_available?'EFIT reference available for this record':'Reference equilibrium unavailable for this record'}. Prediction import is held in this browser session and is not uploaded or persisted.</p>`:''}</div></section><div class="method-block"><h3>Import schema</h3><p>JSON object with <code>schema_version: "1.0.0"</code>, <code>record_id</code> (stable catalog ID or released record ID), <code>dataset_revision</code>, <code>model: {id, version}</code>, <code>units: {psi}</code>, strictly increasing metre coordinate arrays <code>R</code>/<code>Z</code>, ordered <code>timestamps_ms</code>, and <code>frames</code> containing finite <code>psi</code> grids shaped Z × R. The prediction timestamps must match the selected record exactly. Pickle and executable artifacts are not accepted.</p><button class="small-button" id="download-prediction-template">Download JSON schema example</button></div>`}else if(route==='plasma-geometry'){let n=state.catalog.records.reduce((sum,r)=>sum+(r.frames||[]).filter(f=>f.boundary?.length>=3).length,0),f=selectedFrame(),g=f?.geometry,fmt=(v,d=3)=>Number.isFinite(+v)?(+v).toFixed(d):'Unavailable';body=`<div class="geometry-workspace"><section class="panel geometry-figure"><div class="panel-head"><span class="panel-title">SOURCE LCFS / SHAPE CONSTRUCTION</span><span class="head-spacer"></span><span class="head-chip">${g?esc(g.provenance.toUpperCase()):'UNAVAILABLE'}</span></div>${boundarySvg(f)}</section><section class="panel geometry-inspector"><div class="panel-head"><span class="panel-title">FRAME GEOMETRY</span><span class="head-spacer"></span><span class="head-chip">${f?.time_ms==null?'—':fmt(f.time_ms,2)+' ms'}</span></div><div class="geometry-metrics">${[['Magnetic axis R',g?.magnetic_axis?.R_m,'m'],['Magnetic axis Z',g?.magnetic_axis?.Z_m,'m'],['Geometric major radius',g?.major_radius_m,'m'],['Minor radius',g?.minor_radius_m,'m'],['Aspect ratio',g?.aspect_ratio,''],['Inverse aspect ratio',g?.inverse_aspect_ratio,''],['Elongation',g?.elongation,''],['Upper triangularity',g?.triangularity?.upper,''],['Lower triangularity',g?.triangularity?.lower,''],['Cross-sectional area',g?.cross_sectional_area_m2,'m²'],['Boundary perimeter',g?.boundary_perimeter_m,'m'],['Axisymmetric volume',g?.axisymmetric_volume_m3,'m³'],['Vertical displacement',g?.vertical_displacement_m,'m'],['EFIT normalized beta',f?.parameters?.beta_n,''],['EFIT beta-p',f?.parameters?.beta_p,''],['EFIT internal inductance',f?.parameters?.internal_inductance,''],['EFIT q95',f?.parameters?.q95,''],['EFIT elongation',f?.parameters?.efit_elongation,'']].map(([k,v,u])=>`<div class="geometry-metric"><span>${k}</span><b>${fmt(v)} ${u}</b></div>`).join('')}</div><p class="inspector-note">${g?esc(g.method):'No valid source boundary and frame geometry are available.'}</p></section></div><div class="method-block"><h3>Boundary coverage</h3><p>${n} catalog frames contain source LCFS contours. Current record: ${state.record?esc(recordName(state.record)):'none'}. Area uses shoelace integration; volume uses the area centroid and Pappus theorem, not a circular approximation. These derived values use EFIT reference boundaries and are not independent measurements.</p></div>`}else if(route==='settings'){body=`<div class="module-grid"><article class="module-card"><h3>Display</h3><p>Switch the shell between dark and light themes with the appearance control in the top bar.</p><button class="small-button" id="theme-setting">Toggle appearance</button></article><article class="module-card"><h3>Keyboard</h3><p>← / → change recorded frame · Space plays or pauses · R resets the viewport · F toggles fullscreen · 1 opens the explorer.</p></article><article class="module-card"><h3>Local data</h3><p>Catalog: ${state.catalog.records.length} record(s) in this session. Use the reproducible starter bootstrap to populate the local catalog.</p><button class="small-button" id="refresh-setting">Refresh catalog</button></article></div>`}else{body=`<div class="module-grid"><article class="module-card"><div class="module-value">${(label==='FLUX LABORATORY'?state.catalog.records.reduce((n,r)=>n+(r.frames?.length||0),0):state.catalog.records.length)||'—'}</div><h3>${label==='FLUX LABORATORY'?'Equilibrium frames indexed':'Records available locally'}</h3><p>${state.catalog.records.length?'Open the discharge explorer to inspect available data.':'No compatible record artifacts are indexed yet. Load a real source record to activate this workspace.'}</p></article><article class="module-card"><h3>Scientific data required</h3><p>This workspace does not generate experimental signals or predicted equilibria. Import source artifacts with their identity and provenance intact.</p></article><article class="module-card"><h3>Source access</h3><p>Use the official Fusion Equilibrium Challenge configs. Local starter mode is bounded and reproducible.</p><a class="source-link" href="/sources" data-route="sources">Review data sources →</a></article></div>`}
$('#page-content').innerHTML=`<div class="page-heading"><div><div class="eyebrow">RESEARCH MODULE</div><h1>${esc(label.toLowerCase().replace(/\b\w/g,c=>c.toUpperCase()))}</h1><p>${esc(sub)}</p></div><div class="right-caption">${state.catalog.records.length} LOCAL RECORDS</div></div><div class="module-layout">${body}</div>`;if(route==='magnetic-geometry'){const canvas=$('#surface-canvas');surface3d.wire=false;$('#surface-wire').onclick=()=>{surface3d.wire=!surface3d.wire;drawSurface3D()};$('#surface-reset').onclick=()=>{surface3d.yaw=.65;surface3d.pitch=.35;surface3d.zoom=1;drawSurface3D()};canvas.onpointerdown=e=>{surface3d.drag={x:e.clientX,y:e.clientY,yaw:surface3d.yaw,pitch:surface3d.pitch};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(surface3d.drag){surface3d.yaw=surface3d.drag.yaw+(e.clientX-surface3d.drag.x)*.008;surface3d.pitch=Math.max(-1.3,Math.min(1.3,surface3d.drag.pitch+(e.clientY-surface3d.drag.y)*.008));drawSurface3D()}};canvas.onpointerup=()=>surface3d.drag=null;canvas.onwheel=e=>{e.preventDefault();surface3d.zoom=Math.max(.5,Math.min(3,surface3d.zoom*(e.deltaY<0?1.08:.92)));drawSurface3D()};drawSurface3D()}$$('[data-route]').forEach(a=>a.onclick=e=>{e.preventDefault();setRoute(a.dataset.route)});$$('.open-record').forEach(b=>b.onclick=()=>{state.record=state.catalog.records.find(r=>r.id===b.dataset.id);state.machine=state.record.machine;state.frame=0;setRoute('explorer')});$('#catalog-search')?.addEventListener('input',e=>$$('#catalog-body tr').forEach(row=>row.style.display=row.textContent.toLowerCase().includes(e.target.value.toLowerCase())?'':'none'));$('#theme-setting')?.addEventListener('click',toggleTheme);$('#refresh-setting')?.addEventListener('click',loadCatalog);$('#prediction-file')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>250*1024*1024){toast('Prediction file exceeds 250 MB.');return}try{const payload=JSON.parse(await file.text());state.prediction=validatePrediction(payload,state.record);state.fluxSource='prediction';toast('Prediction validated for this record. Open the explorer to inspect it.');renderPage()}catch(error){toast(`Prediction rejected: ${String(error.message||error).slice(0,120)}`);e.target.value=''}});$('#show-prediction')?.addEventListener('click',()=>{state.fluxSource='prediction';setRoute('explorer')});$('#clear-prediction')?.addEventListener('click',()=>{state.prediction=null;state.fluxSource='reference';renderPage()});$('#download-prediction-template')?.addEventListener('click',downloadPredictionTemplate);$('#compare-record')?.addEventListener('change',e=>{state.compareId=e.target.value;renderPage()});$('#open-explorer')?.addEventListener('click',()=>setRoute('explorer'));$('#connect-overview')?.addEventListener('click',()=>{state.route='explorer';renderPage();connectData()})}
function toggleTheme(){document.body.classList.toggle('light');localStorage.setItem('pfe-theme',document.body.classList.contains('light')?'light':'dark');if(state.route==='explorer')drawFlux()}
async function loadCatalog(){try{let r=await fetch('/api/catalog');state.catalog=await r.json();if(!Array.isArray(state.catalog.records))state.catalog.records=[];let good=state.catalog.records;$('#health-dot').classList.toggle('online',good.length>0);$('#health-label').textContent=good.length?'DATA CATALOG READY':'LOCAL WORKSPACE';$('#health-detail').textContent=good.length?`${good.length} curated source record${good.length>1?'s':''}`:'No records indexed';$('#revision-label').textContent=state.catalog.revision||'NOT CONNECTED';if(!state.record)state.record=good.find(x=>x.machine===state.machine)||good[0]||null;renderPage()}catch(error){console.error('Catalog load failed',error);$('#health-detail').textContent=`Catalog unavailable · ${String(error?.message||error).slice(0,36)}`}}
function downloadPredictionTemplate(){if(!state.record){toast('Select a source record first.');return}const sample={schema_version:'1.0.0',record_id:state.record.id,dataset_revision:state.record.revision,model:{id:'your-model-id',version:'1.0.0'},units:{psi:'Wb/rad'},R:state.record.frames?.[0]?.R||[],Z:state.record.frames?.[0]?.Z||[],timestamps_ms:state.record.times||[],frames:(state.record.times||[]).map((time_ms,i)=>({time_ms,psi:state.record.frames?.[i]?.psi||[]}))};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(sample)],{type:'application/json'}));a.download=`${state.record.record_id}-prediction-template.json`;a.click();URL.revokeObjectURL(a.href)}
function exportRecord(){if(!state.record){toast('Load a real source record before exporting scientific data.');return}let f=selectedFrame();if(!f){toast('No reference flux frame is available to export for this record.');return}let payload={record_id:state.record.record_id,configuration:state.record.configuration,provenance:provenance(),dataset_revision:state.catalog.revision||'not recorded',timestamp_ms:f?.time_ms??null,units:{R:'m',Z:'m',psi:'V·s/rad'},frame:f};let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download=`${state.record.id}-frame-${state.frame+1}.json`;a.click();URL.revokeObjectURL(a.href);toast('Current frame exported with provenance metadata.')}
document.addEventListener('click',e=>{let a=e.target.closest('a[data-route]');if(a){e.preventDefault();setRoute(a.dataset.route)}});$('#theme-toggle').onclick=()=>{toggleTheme();if(state.route==='explorer')renderPage()};$('#export-button').onclick=exportRecord;$('#refresh-data').onclick=loadCatalog;$('#menu-toggle').onclick=()=>$('#sidebar').classList.toggle('open');
document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea,[contenteditable=true]'))return;if(e.code==='Space'){e.preventDefault();togglePlay()}else if(e.key==='ArrowRight')step(1);else if(e.key==='ArrowLeft')step(-1);else if(e.key==='r'||e.key==='R'){state.zoom=1;state.panX=state.panY=0;drawFlux()}else if(e.key==='f'||e.key==='F')$('#fullscreen')?.click();else if(e.key==='1')setRoute('explorer');else if(e.key==='Escape'&&$('#sidebar').classList.contains('open'))$('#sidebar').classList.remove('open')});window.addEventListener('resize',()=>{drawFlux();if(state.route==='magnetic-geometry')drawSurface3D()});if(localStorage.getItem('pfe-theme')==='light')document.body.classList.add('light');renderPage();loadCatalog();
